<?php if(!defined('SW_APP')){http_response_code(404);exit;}
$id=$_GET['id']??null;$r=valid_id($id)?one('SELECT r.*,r.total AS ticket_count,r.price_cents AS ticket_price_cents FROM raffles r WHERE id=?',[$id]):null;
if($id&&!$r):empty_state('Sorteo no encontrado','Regresa al listado.');?><a class="btn secondary" href="<?=h(url('participantes'))?>">Volver</a><?php elseif(!$r):$rows=raffle_list(); ?>
<div class="page-heading"><p class="eyebrow">GESTIÓN DE PARTICIPANTES</p><h1>Participantes</h1><p>Selecciona un sorteo para consultar sus boletos y participantes.</p></div><section class="panel"><div class="section-heading"><h2>Seleccionar sorteo</h2></div><div class="toolbar"><input class="search" type="search" data-search="participant-raffles" placeholder="Buscar sorteo..."></div><?php if(!$rows):empty_state('No hay sorteos','Crea un sorteo primero.');else: ?><div class="table-wrap"><table id="participant-raffles"><thead><tr><th>Sorteo</th><th>Estado</th><th>Registrados</th><th>Pagados</th><th></th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><div class="item"><?php photo($x['id'],$x['first_photo']);?><strong><?=h($x['title'])?></strong></div></td><td><?=chip($x['status'])?></td><td><?=(int)$x['registered']?> <?=$x['close_mode']==='capacidad'?' / '.(int)$x['participation_limit']:($x['participation_mode']==='compartido'?' participaciones':' / '.(int)$x['ticket_count'])?></td><td><?=(int)$x['paid']?></td><td><a class="btn primary small" href="<?=h(url('participantes',['id'=>$x['id']]))?>">Ver participantes →</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif;?></section>
<?php else:$id=$r['id'];$p=all('SELECT p.*,p.number AS ticket_number,p.payment AS payment_status,? AS price_cents FROM participants p WHERE raffle_id=? ORDER BY number',[$r['price_cents'],$id]);$paid=count(array_filter($p,fn($x)=>$x['payment_status']==='pagado'));$slots=(int)$r['ticket_count']; ?>
<a class="back" href="<?=h(url('participantes'))?>">← Todos los sorteos</a><div class="page-heading"><p class="eyebrow">PARTICIPANTES POR SORTEO</p><h1><?=h($r['title'])?></h1><p><?=chip($r['status'])?> · <?=money($r['ticket_price_cents'])?> por boleto</p></div><div class="stats"><?php render_stat('Boletos',number_format($slots));render_stat('Registrados',count($p));render_stat('Pagados',$paid);render_stat('Disponibles',$r['close_mode']==='capacidad'?max(0,(int)$r['participation_limit']-count($p)):($r['participation_mode']==='compartido'?'Sin límite':max(0,$slots-count($p))));?></div>
<section class="panel"><div class="section-heading"><h2>Participantes registrados</h2><p><?=$r['participation_mode']==='compartido'?'Una participación por cuenta y número. Varios titulares permitidos.':'Un registro por número de boleto.'?></p></div><div class="toolbar"><?php if($r['status']==='activo'):?><button type="button" class="btn primary" data-open="participant-dialog">＋ Registrar participante</button><?php endif; ?><input type="search" class="search" data-search="participants-table" placeholder="Buscar nombre o número..."></div><?php if(!$p):empty_state('Sin participantes','Los boletos registrados aparecerán aquí.');else: ?><div class="table-wrap"><table id="participants-table"><thead><tr><th>Número</th><th>Nombre</th><th>Correo</th><th>Teléfono</th><th>Pago</th><th>Valor</th><th>Acciones</th></tr></thead><tbody><?php foreach($p as $x):?><tr><td><strong class="ticket-number"><?=h(str_pad((string)$x['ticket_number'],strlen((string)$slots),'0',STR_PAD_LEFT))?></strong></td><td><?=h($x['name'])?></td><td><?=h($x['email']?:'—')?><?php if(!empty($x['user_id'])):?><small class="muted"> · Vinculado</small><?php endif;?></td><td><?=h($x['phone']?:'—')?></td><td><?=chip($x['payment_status'])?></td><td><?=money($x['price_cents'])?></td><td><div class="actions"><?php if($r['status']==='activo'):?><button class="btn secondary small" type="button" data-edit-participant="<?=h(json_encode($x,JSON_INVALID_UTF8_SUBSTITUTE))?>">Editar</button><?php if($x['payment_status']==='pendiente')form_action('delete_participant',$id,'Liberar','danger',$x['id'],'¿Liberar este boleto pendiente?');endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($r['status']==='activo'):?><dialog id="participant-dialog"><form method="post" id="participant-form"><div class="dialog-head"><h2 id="participant-title">Registrar participante</h2><button class="close" type="button" data-close aria-label="Cerrar">×</button></div><div class="dialog-body"><?=csrf()?><input type="hidden" name="action" value="save_participant"><input type="hidden" name="raffle_id" value="<?=h($id)?>"><input type="hidden" name="participant_id" value="0"><label>Nombre completo<input name="name" required maxlength="180"></label><div class="form-grid"><label>Número de boleto<input name="ticket_number" type="number" min="1" max="<?=$slots?>" required></label><label>Estado de pago<select name="payment_status"><option value="pendiente">Pendiente</option><option value="pagado">Pagado</option></select></label></div><label>Correo electrónico<input name="email" type="email" maxlength="254" <?=(int)$r['draw_version']===1?'required':''?>></label><label class="check"><input type="checkbox" name="link_user" value="1"> Vincular a la cuenta verificada de este correo</label><p class="muted tiny">Solo marca esta opción si el titular del boleto es el propietario de la cuenta.</p><label>Teléfono<input name="phone" type="tel" maxlength="50"></label></div><div class="dialog-foot"><button class="btn secondary" type="button" data-close>Cancelar</button><button class="btn primary" type="submit">Guardar</button></div></form></dialog><?php endif;endif; ?>
